vec4 char(vec2 p, int c) {
    if (p.x<.0|| p.x>1. || p.y<0.|| p.y>1.) return vec4(0,0,0,1.0);
	return texture(iChannel1, p/16. + fract(vec2(c, 15-c/16) / 16.));
}


const float pixel_size = 0.01;
const float letter_change_speed = 0.01;


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;

    fragColor = texture(iChannel3, uv);
    // return;






    float aspect_ratio = iResolution.x / iResolution.y;


    vec2 noise_uv = uv - mod(uv, vec2(pixel_size/aspect_ratio, pixel_size));
    vec3 pixel = texture(iChannel3, noise_uv).rgb;
    noise_uv.y = mod(noise_uv.y + letter_change_speed * iTime, 1.0);
    float noise = texture(iChannel2, noise_uv).r;
    noise = round(noise * 25.0 + 65.0);


    vec2 pixel_uv = (
        vec2((1.0/pixel_size)*aspect_ratio, (1.0/pixel_size)) *  
        mod(uv, vec2(pixel_size/aspect_ratio, pixel_size))
    );


    vec3 char = char(pixel_uv, int(noise)).rgb;
    float intensity = length(pixel) / sqrt(3.0);

    vec3 col = vec3(0.0, 2.0 * intensity * char.r, 0.0);



    fragColor = vec4(col,1.0);
}

float getPixel(vec2 uv, float alpha) {
    return length(texture(iChannel0, uv).rgb) * alpha / sqrt(3.0);
}


const float pixel_size = 0.004;


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;    
    float aspect_ratio = iResolution.x / iResolution.y;

    vec2 pixel = vec2(pixel_size/aspect_ratio, pixel_size);
    vec2 noise_uv = uv - mod(uv, pixel);

    vec3 col = texture(iChannel0, noise_uv).rgb;


    float sumX = 0.0;
    float sumY = 0.0;

    // X
    sumX += getPixel(noise_uv + vec2(-pixel.x, pixel.y),-1.0);
    sumX += getPixel(noise_uv + vec2(     0.0, pixel.y),-2.0);
    sumX += getPixel(noise_uv + vec2( pixel.x, pixel.y),-1.0);
    sumX += getPixel(noise_uv + vec2(-pixel.x,-pixel.y), 1.0);
    sumX += getPixel(noise_uv + vec2(     0.0,-pixel.y), 2.0);
    sumX += getPixel(noise_uv + vec2( pixel.x,-pixel.y), 1.0);

    // Y
    sumY += getPixel(noise_uv + vec2(-pixel.x,-pixel.y),-1.0);
    sumY += getPixel(noise_uv + vec2(-pixel.x,     0.0),-2.0);
    sumY += getPixel(noise_uv + vec2(-pixel.x, pixel.y),-1.0);
    sumY += getPixel(noise_uv + vec2( pixel.x,-pixel.y), 1.0);
    sumY += getPixel(noise_uv + vec2( pixel.x,     0.0), 2.0);
    sumY += getPixel(noise_uv + vec2( pixel.x, pixel.y), 1.0);


    float edge = abs(sumX) + abs(sumY);

    // edge = smoothstep(0.0, 0.4, edge);
    // edge = pow(edge, 0.8);

    // float gamma = 2.0;
    // edge = pow(edge, 1.0/gamma);

    edge = step(0.2, edge);



    fragColor = vec4(vec3(edge), 1.0);
}
